import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  const group = new THREE.Group();
  group.userData.cleanup = () => {
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (child.material.map) child.material.map.dispose();
        child.material.dispose();
      }
    });
  };

  // Atlas region: 512x320 from a spritesheet
  // Aspect ratio: 512/320 = 1.6
  const aspectRatio = 512 / 320;
  const planeHeight = 1.6;
  const planeWidth = planeHeight * aspectRatio; // ~2.56

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();

  // Load the sprite texture asynchronously
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;

    // UV offset for atlas region: (0, 0) offset, full region visible
    const atlasUvOffset = new THREE.Vector2(0, 0);
    const atlasUvScale = new THREE.Vector2(1, 1);

    texture.offset.copy(atlasUvOffset);
    texture.repeat.copy(atlasUvScale);

    // TSL-based material with texture node
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  return group;
}
